{
  "title": "Картофельное пюре с курицей",
  "dish_type": "main",
  "difficulty": "easy",
  "cuisine": "русская",
  "total_minutes": 40,
  "active_minutes": 15,
  "servings": 2,
  "description": "Мягкое картофельное пюре с нежной куриным филе. Простое и сытное блюдо на каждый день.",
  "ingredients": [
    {"name": "картофель", "amount": 700, "unit": "g", "is_optional": false},
    {"name": "куриное филе", "amount": 400, "unit": "g", "is_optional": false},
    {"name": "морковь", "amount": 100, "unit": "g", "is_optional": false},
    {"name": "лук репчатый", "amount": 100, "unit": "g", "is_optional": false},
    {"name": "масло растительное", "amount": 30, "unit": "ml", "is_optional": false},
    {"name": "соль", "amount": 1, "unit": "tsp", "is_optional": false}
  ],
  "steps": [
    {
      "text": "Очистить картофель и нарезать крупными кусками.",
      "timer_seconds": null
    },
    {
      "text": "Куриное филе нарезать средними кусками, положить в кастрюлю.",
      "timer_seconds": null
    },
    {
      "text": "Добавить к курице картофель и целую морковь.",
      "timer_seconds": null
    },
    {
      "text": "Залить водой чтобы продукты были покрыты, посолить.",
      "timer_seconds": null
    },
    {
      "text": "Варить на среднем огне 25 минут после закипания.",
      "timer_seconds": 1500
    },
    {
      "text": "Пока варится, нарезать лук и обжарить его на масле до мягкости.",
      "timer_seconds": 480
    },
    {
      "text": "Слить воду, размять картофель с курицей и морковью в пюре.",
      "timer_seconds": null
    },
    {
      "text": "Добавить обжаренный лук, перемешать и прогреть 2 минуты.",
      "timer_seconds": 120
    }
  ]
}
